import api from "./api";
import { getRefreshToken } from "./auth";

export async function logout() {
  const refresh = getRefreshToken();
  if (refresh) {
    try {
      await api.post("/account/logout/", { refresh });
    } catch {
      // Clear local session even if blacklist fails on the server.
    }
  }
}
